// An RFC 7807 Problem Details object. Every non-2xx response carries one. `code` is the stable
// top-level discriminator; `reason` is the fine-grained semantic identity within that class.
// Ref: #/components/schemas/Problem
// Problem represents sum type.
type Problem struct {
	// Type selects the active sum variant, switch on this field.
	Type                   ProblemType
	InvalidProblem         InvalidProblem
	ExecutionFailedProblem ExecutionFailedProblem
	NotFoundProblem        NotFoundProblem
	ConflictProblem        ConflictProblem
	InternalProblem        InternalProblem
}

// ProblemType is oneOf type of Problem.
type ProblemType string

// Possible values for ProblemType.
const (
	InvalidProblemProblem         ProblemType = "invalid"
	ExecutionFailedProblemProblem ProblemType = "execution_failed"
	NotFoundProblemProblem        ProblemType = "not_found"
	ConflictProblemProblem        ProblemType = "conflict"
	InternalProblemProblem        ProblemType = "internal"
)

// IsInvalidProblem reports whether Problem is InvalidProblem.
func (s Problem) IsInvalidProblem() bool { return s.Type == InvalidProblemProblem }

// IsExecutionFailedProblem reports whether Problem is ExecutionFailedProblem.
func (s Problem) IsExecutionFailedProblem() bool { return s.Type == ExecutionFailedProblemProblem }

// IsNotFoundProblem reports whether Problem is NotFoundProblem.
func (s Problem) IsNotFoundProblem() bool { return s.Type == NotFoundProblemProblem }

// IsConflictProblem reports whether Problem is ConflictProblem.
func (s Problem) IsConflictProblem() bool { return s.Type == ConflictProblemProblem }

// IsInternalProblem reports whether Problem is InternalProblem.
func (s Problem) IsInternalProblem() bool { return s.Type == InternalProblemProblem }

// SetInvalidProblem sets Problem to InvalidProblem.
func (s *Problem) SetInvalidProblem(v InvalidProblem) {
	s.Type = InvalidProblemProblem
	s.InvalidProblem = v
}

// GetInvalidProblem returns InvalidProblem and true boolean if Problem is InvalidProblem.
func (s Problem) GetInvalidProblem() (v InvalidProblem, ok bool) {
	if !s.IsInvalidProblem() {
		return v, false
	}
	return s.InvalidProblem, true
}

// NewInvalidProblemProblem returns new Problem from InvalidProblem.
func NewInvalidProblemProblem(v InvalidProblem) Problem {
	var s Problem
	s.SetInvalidProblem(v)
	return s
}

